#include <bits/stdc++.h>
using namespace std;

class CF884F : public std::ostream {
public:
    CF884F() : std::ostream(std::cout.rdbuf()) {}
    void main();

private:
    static const int A = 26, INF = 0x3f3f3f3f;
    int m_, n_;
    std::vector<int> oo, oh, ii, jj, cc, cost, cost_;
    std::vector<int> ae, pi, dd, ff;
    std::vector<int> pq, iq;
    std::vector<int> oo_b, oh_b, cc_b;
    std::vector<int> bb;
    int __ = 1, cnt;

    int link(int o, int h, std::vector<int>& oo, std::vector<int>& oh) {
        oo[h] = o;
        oh[h] = __;
        return __++;
    }

    bool less(int u, int v, const std::vector<int>& pi, const std::vector<int>& dd) {
        return pi[u] < pi[v] || (pi[u] == pi[v] && dd[u] < dd[v]);
    }

    int i2(int i) {
        int res = i * 2;
        if (res > cnt) return 0;
        if (res < cnt && less(pq[iq[pq[res]]], pq[res], pi, dd))
            return res + 1;
        return res;
    }

    void pq_up(int u, std::vector<int>& pq, std::vector<int>& iq, const std::vector<int>& pi, const std::vector<int>& dd) {
        int i = iq[u];
        while (i > 1) {
            int j = i / 2;
            int v = pq[j];
            if (less(u, v, pi, dd)) {
                pq[iq[v]] = i;
                pq[iq[u] = i] = u;
                i = j;
            } else break;
        }
        if (iq[u] != i) {
            pq[iq[u]] = u;
        }
    }

    void pq_dn(int u, std::vector<int>& pq, std::vector<int>& iq, const std::vector<int>& pi, const std::vector<int>& dd) {
        int i = iq[u];
        while (true) {
            int j = i2(i);
            if (j == 0) break;
            int v = pq[j];
            if (less(v, u, pi, dd)) {
                pq[iq[v]] = i;
                pq[iq[u] = i] = u;
                i = j;
            } else break;
        }
        if (iq[u] != i) {
            pq[iq[u]] = u;
        }
    }

    void pq_add_last(int u, std::vector<int>& pq, std::vector<int>& iq, int& cnt) {
        pq[++cnt] = u;
        iq[u] = cnt;
    }

    int pq_remove_first(std::vector<int>& pq, std::vector<int>& iq, int& cnt) {
        int u = pq[1];
        int v = pq[cnt--];
        if (v != u) {
            iq[v] = 1;
            pq_dn(v, pq, iq, pi, dd);
        }
        iq[u] = 0;
        return u;
    }

    bool dijkstra(int s, int t, std::vector<int>& oo, std::vector<int>& oh, std::vector<int>& ae,
                  std::vector<int>& pi, std::vector<int>& dd, std::vector<int>& ff,
                  std::vector<int>& pq, std::vector<int>& iq, int& cnt, const std::vector<int>& cost_, const std::vector<int>& cc_b, const std::vector<int>& bb, int m) {
        std::fill(pi.begin(), pi.end(), INF);
        pi[s] = 0;
        cnt = 0;
        pq_add_last(s, pq, iq, cnt);
        while (cnt > 0) {
            int i = pq_remove_first(pq, iq, cnt);
            int d = dd[i] + 1; 
            for (int o = ae[i]; o != 0; o = oo[o]) {
                int h_ = oh[o];
                if (cc_b[h_] > 0) {
                    int h = h_ >> 1;
                    int j = i ^ ii[h] ^ jj[h];
                    int p = pi[i] + (((h_ & 1) == 0) ? cost_[h] : -cost_[h]);
                    if (pi[j] > p || (pi[j] == p && dd[j] > d)) {
                        if (pi[j] == INF) {
                            pq_add_last(j, pq, iq, cnt);
                        }
                        pi[j] = p; dd[j] = d; ff[j] = h_;
                        pq_up(j, pq, iq, pi, dd);
                    }
                }
            }
        }
        return pi[t] != INF;
    }

    int trace(int s, int t, std::vector<int>& cc_b, std::vector<int>& ff, std::vector<int>& ii, std::vector<int>& jj) {
        while (t != s) {
            int h_ = ff[t], h = h_ >> 1;
            cc_b[h_]--; cc_b[h_ ^ 1]++;
            t ^= ii[h] ^ jj[h];
        }
        return 1;
    }

    int edmonds_karp(int s, int t, int m, std::vector<int>& oo, std::vector<int>& oh, std::vector<int>& ii, std::vector<int>& jj,
                       std::vector<int>& cc_b, std::vector<int>& cost_, std::vector<int>& pi, std::vector<int>& dd, std::vector<int>& ff,
                       std::vector<int>& pq, std::vector<int>& iq, int& cnt, const std::vector<int>& cc, const std::vector<int>& bb,
                       std::vector<int>& cost) {
        const int n = cc.size();
        for (int h = 0; h < m; h++) {
            int i = ii[h], j = jj[h];
            pi[j] = std::min(pi[j], pi[i] + cost[h]);
        }
        for (int h = 0; h < m; h++) {
            int i = ii[h], j = jj[h];
            cost_[h] = cost[h] + pi[i] - pi[j];
        }
        int f = 0;
        while (dijkstra(s, t, oo, oh, ae, pi, dd, ff, pq, iq, cnt, cost_, cc_b, bb, m)) {
            f += trace(s, t, cc_b, ff, ii, jj);
            for (int h = 0; h < m; h++) {
                int i = ii[h], j = jj[h];
                if (pi[i] != INF && pi[j] != INF) {
                    cost_[h] += pi[i] - pi[j];
                }
            }
        }
        int ans = 0;
        for (int h = 0; h < m; h++) {
            ans += cc_b[h * 2 + 1] * cost[h];
        }
        return ans;
    }

public:
    void main() {
        int n_input;
        std::cin >> n_input;
        n_input /= 2;
        n = n_input;
        int total_vertices = 1 + n + A + 1;

        oo.assign(1 + 2 * n + A, 0);
        oh.assign(1 + 2 * n + A, 0);
        ii.assign(n + n * A + A, 0);
        jj.assign(n + n * A + A, 0);
        cc.assign(n + n, 0);
        cost.assign(n, 0);
        cost_.assign(n, 0);
        pi.assign(total_vertices, 0);
        dd.assign(total_vertices, 0);
        ff.assign(total_vertices, 0);
        ae.assign(total_vertices, 0);
        pq.assign(total_vertices + 1, 0);
        iq.assign(total_vertices, 0);
        cc_b.assign(total_vertices, 0);
        bb.assign(2 * n, 0);
        m_ = 0;
        int total_edges = 0;

        std::string s;
        std::cin >> s;
        std::vector<int> bb_array(2 * n);
        for (int i = 0; i < 2 * n; i++) {
            std::cin >> bb_array[i];
        }
        for (int i = 0; i < n; i++) {
            int h = link(0, 1 + i, oo, oh);
        }
        std::vector<int> cc_chars(2 * n);
        for (int i = 0; i < 2 * n; i++) {
            cc_chars[i] = s[i];
        }
        for (int i = 0; i < n; i++) {
            int j = 2 * n - 1 - i;
            int ai = cc_chars[i] - 'a';
            int aj = cc_chars[j] - 'a';
            for (int a = 0; a < A; a++) {
                int b;
                if (a == ai && a == aj)
                    b = std::max(bb_array[i], bb_array[j]);
                else if (a == ai)
                    b = bb_array[i];
                else if (a == aj)
                    b = bb_array[j];
                else
                    b = 0;
                link(link(0, 0, oo, oh), link(0, 0, oo, oh), oo, oh);
                int h_idx = link(1 + i, 1 + n + a, oo, oh);
                cc[h_idx] = 1;
                cost[h_idx] = -b;
                link(h_idx, 0, oo, oh);
                total_edges++;
            }
        }
        int kk[A] = {0};
        for (int i = 0; i < 2 * n; i++) {
            int a = cc_chars[i] - 'a';
            kk[a]++;
        }
        for (int a = 0; a < A; a++)
            link(link(1 + n + a, total_vertices - 1, oo, oh), link(1 + n + a, total_vertices - 1, oo, oh), oo, oh);
        int answer = -edmonds_karp(0, total_vertices - 1, total_edges, oo, oh, ii, jj, cc_b, cost_, pi, dd, ff, pq, iq, cnt, cc, bb, cost);
        std::cout << answer << "\n";
    }
};

int main() {
    CF884F solver;
    solver.main();
    return 0;
}

